using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tools ---
var notebook = new Notebook();
var webSearch = new WebSearcher();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearch.SearchAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// --- Chat client with automatic function invocation ---
IChatClient client = new ChatClientBuilder(
        new OpenAIClient(openAiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var options = new ChatOptions
{
    Tools = [.. tools],
    Temperature = 0.3f,
};

// --- Agent loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent                 ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Commands:                               ║");
Console.WriteLine("║    Type a topic to research              ║");
Console.WriteLine("║    'notes'  – view saved notes           ║");
Console.WriteLine("║    'exit'   – quit                       ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

var history = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. When the user gives you a topic:
        1. Use the SearchWeb tool to find relevant information (perform 2-3 searches with different queries).
        2. Use AddNote to save the most important findings as you go.
        3. After gathering enough information, provide a well-structured summary that cites the sources.
        Always search before answering. Be thorough but concise.
        """),
};

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("You> ");
    Console.ResetColor();

    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(input)) continue;

    if (input.Equals("exit", StringComparison.OrdinalIgnoreCase)) break;

    if (input.Equals("notes", StringComparison.OrdinalIgnoreCase))
    {
        var saved = notebook.GetNotes();
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine(saved);
        Console.ResetColor();
        continue;
    }

    history.Add(new(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("  [researching…]");
    Console.ResetColor();

    try
    {
        var response = await client.GetResponseAsync(history, options);

        // Append assistant response to history for multi-turn conversation.
        foreach (var msg in response.Messages)
            history.Add(msg);

        Console.ForegroundColor = ConsoleColor.Green;
        Console.Write("Agent> ");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"  Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");
return;

