/// <summary>Searches the web using the Brave Search API or falls back to DuckDuckGo HTML.</summary>
sealed class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query and return a summary of results.")]
    public async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use DuckDuckGo HTML lite – no API key required.
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);
            return ParseDuckDuckGoResults(html, maxResults: 5);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string ParseDuckDuckGoResults(string html, int maxResults)
    {
        var sb = new StringBuilder();
        var count = 0;

        // Simple extraction of result snippets from DDG HTML lite.
        var snippetMarker = "result__snippet";
        var titleMarker = "result__a";
        var idx = 0;

        while (count < maxResults && idx < html.Length)
        {
            // Find next title
            var titlePos = html.IndexOf(titleMarker, idx, StringComparison.Ordinal);
            if (titlePos < 0) break;

            var titleStart = html.IndexOf('>', titlePos);
            if (titleStart < 0) break;
            titleStart++;
            var titleEnd = html.IndexOf('<', titleStart);
            var title = titleEnd > titleStart
                ? StripHtml(html[titleStart..titleEnd]).Trim()
                : "";

            // Extract href
            var hrefStart = html.LastIndexOf("href=\"", titlePos, Math.Min(titlePos, 200), StringComparison.Ordinal);
            var href = "";
            if (hrefStart >= 0)
            {
                hrefStart += 6;
                var hrefEnd = html.IndexOf('"', hrefStart);
                if (hrefEnd > hrefStart)
                    href = html[hrefStart..hrefEnd];
            }

            // Find snippet
            var snippetPos = html.IndexOf(snippetMarker, titlePos, StringComparison.Ordinal);
            var snippet = "";
            if (snippetPos >= 0)
            {
                var sStart = html.IndexOf('>', snippetPos);
                if (sStart >= 0)
                {
                    sStart++;
                    var sEnd = html.IndexOf("</", sStart, StringComparison.Ordinal);
                    if (sEnd > sStart)
                        snippet = StripHtml(html[sStart..sEnd]).Trim();
                }
            }

            if (!string.IsNullOrWhiteSpace(title))
            {
                count++;
                sb.AppendLine($"[{count}] {title}");
                if (!string.IsNullOrWhiteSpace(href))
                    sb.AppendLine($"    URL: {href}");
                if (!string.IsNullOrWhiteSpace(snippet))
                    sb.AppendLine($"    {snippet}");
                sb.AppendLine();
            }

            idx = titlePos + titleMarker.Length;
        }

        return count == 0
            ? "No results found."
            : sb.ToString();
    }

    private static string StripHtml(string s) =>
        System.Text.RegularExpressions.Regex.Replace(s, "<[^>]+>", " ")
            .Replace("&amp;", "&")
            .Replace("&lt;", "<")
            .Replace("&gt;", ">")
            .Replace("&quot;", "\"")
            .Replace("&#x27;", "'");
}

/// <summary>Simple in-memory notebook for saving and retrieving research notes.</summary>
sealed class Notebook
{
    private readonly List<(DateTime Time, string Note)> _notes = [];

    [Description("Save a research note. Use this to record important findings from web searches.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add((DateTime.UtcNow, note));
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        Console.ResetColor();
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var (time, note) = _notes[i];
            sb.AppendLine($"[{i + 1}] ({time:HH:mm:ss}) {note}");
        }

        return sb.ToString();
    }
}

